using Microsoft.UI;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Markup;
using Microsoft.UI.Xaml.Media;
using XamlPath = Microsoft.UI.Xaml.Shapes.Path;
using Windows.Foundation;
using Windows.UI;
using UpdateAllWin.Contracts;

namespace UpdateAllWin.Toolbar;

/// <summary>
/// The UpdateAll Win logo as vectors (two circling arrows around the four Windows tiles).
/// Geometry is generated by build/logo/make_logo.py so it matches the .ico/.png files exactly.
/// </summary>
public sealed partial class LogoMark : UserControl
{
    private const string BluePath = "M185.73,39.10 A106.0,106.0 0 0 0 23.03,142.75 L6.20,145.12 L52.95,179.47 L69.57,136.21 L52.74,138.58 A76.0,76.0 0 0 1 169.39,64.26 Z";
    private const string TealPath = "M62.74,211.53 A106.0,106.0 0 0 0 231.68,105.96 L248.31,102.43 L199.27,71.42 L185.71,115.73 L202.34,112.20 A76.0,76.0 0 0 1 81.21,187.89 Z";
    private const double TileOrigin = 79.5, TileSize = 45, TileGap = 7, TileRadius = 8;

    public LogoMark()
    {
        var canvas = new Canvas { Width = 256, Height = 256 };
        canvas.Children.Add(new XamlPath
        {
            Data = Parse(BluePath),
            Fill = Gradient(Color.FromArgb(255, 0x2A, 0x8C, 0xF0), Color.FromArgb(255, 0x0B, 0x3E, 0xB5), new Point(1, 0), new Point(0, 1)),
        });
        canvas.Children.Add(new XamlPath
        {
            Data = Parse(TealPath),
            Fill = Gradient(Color.FromArgb(255, 0x13, 0xB8, 0xC8), Color.FromArgb(255, 0x2E, 0xE6, 0xA6), new Point(0, 1), new Point(1, 0)),
        });
        canvas.Children.Add(new XamlPath
        {
            Data = Parse(TilesPath()),
            Fill = Gradient(Color.FromArgb(255, 0x5C, 0xCF, 0xFF), Color.FromArgb(255, 0x0D, 0x4F, 0xC8), new Point(0, 0), new Point(1, 1)),
        });
        Content = new Viewbox { Child = canvas, Stretch = Stretch.Uniform };
        IsHitTestVisible = false;
    }

    private static string TilesPath()
    {
        var parts = new List<string>();
        for (var row = 0; row < 2; row++)
        for (var col = 0; col < 2; col++)
        {
            double x = TileOrigin + col * (TileSize + TileGap), y = TileOrigin + row * (TileSize + TileGap), s = TileSize, r = TileRadius;
            parts.Add(FormattableString.Invariant(
                $"M{x + r},{y} L{x + s - r},{y} A{r},{r} 0 0 1 {x + s},{y + r} L{x + s},{y + s - r} A{r},{r} 0 0 1 {x + s - r},{y + s} L{x + r},{y + s} A{r},{r} 0 0 1 {x},{y + s - r} L{x},{y + r} A{r},{r} 0 0 1 {x + r},{y} Z"));
        }
        return string.Join(" ", parts);
    }

    private static Geometry Parse(string data) => (Geometry)XamlBindingHelper.ConvertValue(typeof(Geometry), data);

    private static LinearGradientBrush Gradient(Color from, Color to, Point start, Point end) => new()
    {
        StartPoint = start,
        EndPoint = end,
        GradientStops = { new GradientStop { Color = from, Offset = 0 }, new GradientStop { Color = to, Offset = 1 } },
    };
}

/// <summary>Toolbar/tray status colours from the spec.</summary>
public static class StatusVisuals
{
    public static Color ColorFor(OverallStatus status) => status switch
    {
        OverallStatus.UpToDate => Color.FromArgb(255, 0x22, 0xC5, 0x5E),        // green
        OverallStatus.Busy => Color.FromArgb(255, 0x25, 0x63, 0xEB),            // blue
        OverallStatus.UpdatesAvailable => Color.FromArgb(255, 0xF9, 0x73, 0x16), // orange
        OverallStatus.Failed => Color.FromArgb(255, 0xEF, 0x44, 0x44),           // red
        OverallStatus.RestartRequired => Color.FromArgb(255, 0xEA, 0xB3, 0x08),  // yellow
        _ => Color.FromArgb(255, 0x94, 0xA3, 0xB8),                                  // grey
    };

    public static string TrayIconFile(OverallStatus status) => status switch
    {
        OverallStatus.UpToDate => "Tray-green.ico",
        OverallStatus.Busy => "Tray-blue.ico",
        OverallStatus.UpdatesAvailable => "Tray-orange.ico",
        OverallStatus.Failed => "Tray-red.ico",
        OverallStatus.RestartRequired => "Tray-yellow.ico",
        _ => "Tray-grey.ico",
    };

    public static OverallStatus From(EngineStatus? status, bool serviceAvailable) =>
        !serviceAvailable || status is null ? OverallStatus.Unknown : status.Overall;
}
